mapper.select:
SELECT i.assignee_id, u.display_name AS assignee_name, COUNT(*) AS total, COUNT(*) FILTER (WHERE i.status_id IN
#{sid}
) AS done_count FROM issue i LEFT JOIN sys_user u ON u.id = i.assignee_id WHERE i.deleted_at IS NULL
GROUP BY i.assignee_id, u.display_name ORDER BY total DESC

SELECT COUNT(*) AS total,
       COUNT(*) FILTER (WHERE i.status_id NOT IN

               #{sid}

       ) AS open_count,
       COUNT(*) FILTER (WHERE i.status_id IN

               #{sid}

       ) AS closed_count,
       COUNT(*) FILTER (WHERE i.assignee_id IS NULL) AS unassigned,
       COUNT(*) FILTER (WHERE i.due_date IS NOT NULL
           AND i.due_date < CAST(#{now} AS DATE)
           AND i.status_id NOT IN

               #{sid}

       ) AS overdue
FROM issue i
WHERE i.deleted_at IS NULL

SELECT p.id AS project_id,
       p.name AS project_name,
       p.key AS project_key,
       COUNT(*) AS total,
       COUNT(*) FILTER (WHERE i.status_id NOT IN

               #{sid}

       ) AS open_count,
       COUNT(*) FILTER (WHERE i.status_id IN

               #{sid}

       ) AS closed_count,
       COUNT(*) FILTER (WHERE i.due_date IS NOT NULL
           AND i.due_date < CAST(#{now} AS DATE)
           AND i.status_id NOT IN

               #{sid}

       ) AS overdue
FROM issue i
JOIN project p ON p.id = i.project_id
WHERE i.deleted_at IS NULL


        AND i.project_id = #{projectIds[0]}


        AND i.project_id IN

            #{pid}



GROUP BY p.id, p.name, p.key
ORDER BY total DESC

SELECT t.user_id, u.display_name AS user_name, COALESCE(SUM(t.duration), 0) AS total_minutes FROM time_entry t JOIN issue i ON i.id = t.issue_id JOIN sys_user u ON u.id = t.user_id WHERE i.deleted_at IS NULL AND t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date
AND i.project_id IN #{pid}
GROUP BY t.user_id, u.display_name ORDER BY total_minutes DESC

SELECT p.id AS project_id, p.name AS project_name, COALESCE(SUM(t.duration), 0) AS total_minutes FROM time_entry t JOIN issue i ON i.id = t.issue_id JOIN project p ON p.id = i.project_id WHERE i.deleted_at IS NULL AND t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date
AND i.project_id IN #{pid}
GROUP BY p.id, p.name ORDER BY total_minutes DESC

SELECT COALESCE(wiav.name, '未分类') AS work_type, COALESCE(SUM(t.duration), 0) AS total_minutes FROM time_entry t JOIN issue i ON i.id = t.issue_id LEFT JOIN time_entry_attribute_value teav ON teav.time_entry_id = t.id AND teav.attribute_id = #{workTypeAttributeId} LEFT JOIN work_item_attribute_value wiav ON wiav.id = teav.value_id WHERE i.deleted_at IS NULL AND t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date
AND i.project_id IN #{pid}
GROUP BY COALESCE(wiav.name, '未分类') ORDER BY total_minutes DESC

SELECT t.work_date::text AS work_date, COALESCE(SUM(t.duration), 0) AS total_minutes FROM time_entry t JOIN issue i ON i.id = t.issue_id WHERE i.deleted_at IS NULL AND t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date
AND i.project_id IN #{pid}
GROUP BY t.work_date ORDER BY t.work_date ASC

SELECT p.name AS project_name, u.display_name AS user_name, COALESCE(SUM(t.duration), 0) AS total_minutes FROM time_entry t JOIN issue i ON i.id = t.issue_id JOIN project p ON p.id = i.project_id JOIN sys_user u ON u.id = t.user_id WHERE i.deleted_at IS NULL AND t.work_date >= #{startDate}::date AND t.work_date <= #{endDate}::date
AND i.project_id IN #{pid}
GROUP BY p.name, u.display_name ORDER BY p.name ASC, total_minutes DESC

SELECT i.id AS issue_id, i.issue_key, i.title, p.name AS project_name, COALESCE(u.display_name, '未分配') AS assignee_name, i.estimated_hours, i.spent_hours FROM issue i JOIN project p ON p.id = i.project_id LEFT JOIN sys_user u ON u.id = i.assignee_id WHERE i.deleted_at IS NULL AND i.estimated_hours IS NOT NULL AND i.estimated_hours > 0
AND i.project_id IN #{pid}
ORDER BY (COALESCE(i.spent_hours, 0) / i.estimated_hours) DESC LIMIT #{limit} OFFSET #{offset}

SELECT p.name AS project_name, SUM(i.estimated_hours) AS estimated_hours_sum, COALESCE(SUM(i.spent_hours), 0) AS spent_hours_sum, COUNT(*) AS issue_count FROM issue i JOIN project p ON p.id = i.project_id WHERE i.deleted_at IS NULL AND i.estimated_hours IS NOT NULL AND i.estimated_hours > 0
AND i.project_id IN #{pid}
GROUP BY p.name ORDER BY estimated_hours_sum DESC
